    comunicado_id: b.comunicado_id,
    emisor: b.emisor,
    destinatario: b.destinatario || 'estudiantes@cefic.edu.pe',
    asunto: b.asunto,
    cuerpo: b.cuerpo,

    // En uso real la categoria verdadera se desconoce.
    // Solo se envia en pruebas controladas.
    categoria_real: b.categoria_real || 'no_etiquetado',
    hora_ingreso: fecha
  }
}];

const listaBlanca = [
  'direccion@cefic.edu.pe',
  'secretaria.academica@instituto.edu.pe',
  'direccion.general@instituto.edu.pe',
  'coordinacion@instituto.edu.pe'
];

return items.map(item => {
  const emisor = String(item.json.emisor || '').trim().toLowerCase();
  item.json.emisor = emisor;
  item.json.emisor_autorizado = listaBlanca.includes(emisor);
  item.json.control_validacion_origen = true;
  return item;
});

return items.map(item => {
  const texto = `${item.json.asunto || ''} ${item.json.cuerpo || ''}`.toLowerCase();

  const patrones = [
    'urgente',
    'contraseña',
    'password',
    'credenciales',
    'ingrese al siguiente enlace',
    'verifique su cuenta',
    'confirme sus credenciales',
    'premio',
    'transferencia',
    'archivo adjunto'
  ];

  const coincidencias = patrones.filter(p => texto.includes(p));

  item.json.patrones_sospechosos = coincidencias;
  item.json.contenido_sospechoso = coincidencias.length > 0;
  item.json.control_filtrado = true;

  return item;
});

return items.map(item => {
  item.json.prompt_groq = `Actúa como analista de ciberseguridad.

Analiza el siguiente comunicado institucional y clasifícalo como phishing, spam o legitimo.

Asigna un score de riesgo entero entre 1 y 10.

Responde EXCLUSIVAMENTE con JSON válido:
{"categoria":"phishing|spam|legitimo","score":1,"justificacion":"texto breve"}

Emisor: ${item.json.emisor}
Emisor autorizado: ${item.json.emisor_autorizado}
Destinatario: ${item.json.destinatario}
Asunto: ${item.json.asunto}
Cuerpo: ${item.json.cuerpo}
Patrones sospechosos: ${JSON.stringify(item.json.patrones_sospechosos)}`;

  return item;
});

const original = $('Filtrar contenido').item.json;

let raw = '';
try {
  raw = $json.choices[0].message.content;
} catch (e) {
  raw = '';
}

let resultado;
try {
  resultado = JSON.parse(
    String(raw)
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim()
  );
} catch (e) {
  // Si Groq falla o responde algo ilegible: riesgo medio => se pausa (fail-closed)
  resultado = {
    categoria: 'indeterminado',
    score: 5,
    justificacion: 'No se pudo interpretar la respuesta del modelo.'
  };
}

let score = Number(resultado.score);
if (!Number.isFinite(score)) score = 5;
score = Math.max(1, Math.min(10, Math.round(score)));

